{
  "name": "reservation_cancelled",
  "description": "Tell the messaging agent that a reservation was cancelled.",
  "input_schema": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "id",
      "reservation",
      "slot",
      "source"
    ],
    "properties": {
      "id": {
        "type": "string",
        "pattern": "^evt_[0-9]+$"
      },
      "reservation": {
        "type": "string",
        "pattern": "^R[0-9]+$"
      },
      "slot": {
        "type": "string",
        "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun) [0-2][0-9]:[0-5][0-9]$"
      },
      "source": {
        "enum": [
          "restaurant",
          "bookings"
        ]
      }
    }
  }
}
